async function checkDatabaseConnection() {
  const dbUri = process.env.DATABASE_URI;
  if (!dbUri) {
    console.error('DATABASE_URI is not set');
    return;
  }

  try {
    await mongoose.connect(dbUri, { useNewUrlParser: true, useUnifiedTopology: true });
